// ESP32 — Bodenfeuchte-Sensor YL-69
#define SENSOR_PIN 34
#define DRY_VALUE  3500  // Sensor in der Luft / in trockener Erde messen
#define WET_VALUE   800  // Sensor in Wasser tauchen und Wert ablesen

void setup() {
  Serial.begin(115200);
  Serial.println("Pflanzenwächter startet...");
}

void loop() {
  int raw = analogRead(SENSOR_PIN);
  int percent = map(raw, DRY_VALUE, WET_VALUE, 0, 100);
  percent = constrain(percent, 0, 100);

  Serial.print("Rohwert: ");
  Serial.print(raw);
  Serial.print("  |  Feuchte: ");
  Serial.print(percent);
  Serial.println(" %");

  if (percent < 30) {
    Serial.println("Bitte giessen!");
  }

  delay(2000);
}
